def names(self, all=False):  # pylint:disable=redefined-builtin
        """Return the attribute names defined by the interface.

        If ``all`` is ``False`` (the default), only the names of attributes
        currently defined on the instance (i.e. present in ``self.__dict__``)
        are returned.  Private attributes – ones that start with an
        underscore – are omitted.  If ``all`` is ``True``, the method
        aggregates the names of all public instance attributes that are
        defined on the class or any of its base classes.  The result is a
        list sorted alphabetically.

        The method is tolerant of objects that do not have a ``__dict__``
        attribute (for example, classes that use ``__slots__``); in that
        case ``all=False`` will simply return an empty list, and
        ``all=True`` will still return class‑defined attribute names.
        """
        try:
            if all:
                # Gather names from the class hierarchy, excluding
                # private names and callables.
                seen = set()
                for cls in type(self).__mro__:
                    for name, val in cls.__dict__.items():
                        if name.startswith('_'):
                            continue
                        if callable(val):
                            continue
                        seen.add(name)
                return sorted(seen)
            else:
                # Instance-level attributes only.
                instance_attrs = [
                    key for key, value in vars(self).items()
                    if not key.startswith('_')
                ]
                return sorted(instance_attrs)
        except AttributeError:
            # Fall back to empty list if __dict__ is not available.
            return []

