def _get_err_indices(self, coord_name):
    """
    Get error indices corresponding to a coordinate.

    This method searches common attributes that may store error
    information (boolean masks, integer index lists, or dictionaries)
    and returns a list of integer indices where an error is present
    for the specified coordinate.  If no error information is found,
    an empty list is returned.
    """
    # Helper to convert any iterable of indices to a list of ints
    def _to_int_list(val):
        if isinstance(val, (list, tuple)):
            return [int(v) for v in val if v is not None]
        try:
            # treat scalar / single value
            return [int(val)]
        except Exception:
            return []

    # Names of attributes that may contain error indices
    candidate_attrs = [
        'err_indices', 'error_indices',  # dictionary mapping name -> indices
        'errors', 'err_index', 'error',
        'error_index', 'err_idxs', 'error_idxs'
    ]

    for attr in candidate_attrs:
        if hasattr(self, attr):
            data = getattr(self, attr)
            # Case 1: dictionary mapping coordinate names to indices
            if isinstance(data, dict):
                if coord_name in data:
                    return _to_int_list(data[coord_name])
            # Case 2: list/tuple/ndarray where each entry corresponds to a coordinate
            if isinstance(data, (list, tuple)):
                # Try to infer order from a parallel attribute holding coordinate names
                coord_names = None
                for name_candidate in ('coord_names', 'coords', 'coordinate_names'):
                    if hasattr(self, name_candidate):
                        coord_names = getattr(self, name_candidate)
                        break
                if coord_names and coord_name in coord_names:
                    idx = coord_names.index(coord_name)
                    if idx < len(data):
                        return _to_int_list(data[idx])
            # Case 3: boolean mask array/list of the same length as the coordinate array
            if isinstance(data, (list, tuple)):
                # Identify if data is a list of booleans
                try:
                    bool_mask = all(isinstance(v, bool) for v in data)
                except Exception:
                    bool_mask = False
                if bool_mask:
                    return [i for i, v in enumerate(data) if v]
        # If attribute not found, continue checking next candidate

    # Fallback: check if coordinate itself has an associated error attribute
    # e.g., obj.x_err, obj['x_err'], or obj.variables['x_err']
    suffixes = ['_err', 'Err', 'ERROR']
    for suffix in suffixes:
        err_attr = f"{coord_name}{suffix}"
        if hasattr(self, err_attr):
            err_data = getattr(self, err_attr)
            if isinstance(err_data, dict) and coord_name in err_data:
                return _to_int_list(err_data[coord_name])
            if isinstance(err_data, (list, tuple)):
                # boolean mask
                try:
                    if all(isinstance(v, bool) for v in err_data):
                        return [i for i, v in enumerate(err_data) if v]
                except Exception:
                    pass
                return _to_int_list(err_data)

    # Attempt to read from a generic 'variables' dictionary
    if hasattr(self, 'variables'):
        vars_dict = getattr(self, 'variables')
        if isinstance(vars_dict, dict):
            if coord_name in vars_dict:
                val = vars_dict[coord_name]
                # boolean mask
                if isinstance(val, (list, tuple)):
                    try:
                        if all(isinstance(v, bool) for v in val):
                            return [i for i, v in enumerate(val) if v]
                    except Exception:
                        pass
                    return _to_int_list(val)

    # If no error information is found, return an empty list
    return []<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Direct element check
        if isinstance(seq, FillRequest):
            return True
        # Source sequence check
        if isinstance(seq, Source):
            return False
        # Iterable check
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False
    except Exception:
        # Any unexpected exception should result in False
        return False
    return False<|return|>

