        else:
            if key_regex is not None and not key_regex.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex {key_regex.pattern}"}
                )
        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            if value_regex is not None and not value_regex.match(value):
                errors.append(
                    {value: f"Label value '{value}' does not match the regex {value_regex.pattern}"}
                )
    if errors:
        raise ValidationError(errors)<|return|>

