def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Default schema applied when no custom observer schema is provided
    default_schema = {
        "type": "object",
        "properties": {
            "status": {"type": "object"},
        },
    }

    result = {}

    try:
        # Try to fetch the manifests list; fallback to empty iterable if missing
        manifests = getattr(app, "spec", {}).get("manifest", [])
        if not isinstance(manifests, (list, tuple)):
            return result
    except Exception:
        return result

    for resource in manifests:
        # Skip non-dict resources
        if not isinstance(resource, dict):
            continue

        # Build a key for the resource, prioritize kind/name, fallback to index
        try:
            kind = resource.get("kind", "UnknownKind")
            name = resource.get("metadata", {}).get("name", f"resource_{len(result)}")
            key = f"{kind}:{name}"
        except Exception:
            key = f"resource_{len(result)}"

        # Determine if a custom observer schema is already defined
        custom_schema_found = False
        try:
            # Assuming custom schemas are stored in the 'spec' section under 'observer_schema'
            custom_schema = resource.get("spec", {}).get("observer_schema", None)
            if custom_schema:
                custom_schema_found = True
        except Exception:
            # If anything goes wrong, treat as no custom schema
            custom_schema_found = False

        if not custom_schema_found:
            result[key] = default_schema

    return result<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Ensure a non-empty path
    if not path:
        return False
    # Convert pyfs Root or other path-like objects to string
    try:
        # os.fspath works for objects supporting the Path protocol
        path_str = os.fspath(path)
    except Exception:
        return False
    # The path must exist and be a directory
    try:
        if not os.path.isdir(path_str):
            return False
    except OSError:
        return False
    # An OCFL object root typically contains a '.ocfl' directory
    ocfl_dir = os.path.join(path_str, ".ocfl")
    try:
        if not os.path.isdir(ocfl_dir):
            return False
    except OSError:
        return False
    # At least one version directory inside '.ocfl' (e.g., '00000001')
    try:
        entries = os.listdir(ocfl_dir)
    except OSError:
        return False
    for entry in entries:
        full = os.path.join(ocfl_dir, entry)
        if os.path.isdir(full):
            return True
    # If no suitable directories were found, consider it invalid
    return False<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Determine the log attribute; support typical names
    log_attr = getattr(self, "validation_log", None)
    if log_attr is None:
        log_attr = getattr(self, "log", None)
    if log_attr is None:
        return ""
    # If the log is a mapping, convert to list of values
    if isinstance(log_attr, dict):
        entries = list(log_attr.values())
    else:
        entries = list(log_attr)
    lines = []
    for entry in entries:
        try:
            line = str(entry)
        except Exception:
            line = repr(entry)
        if prefix:
            line = f"{prefix}{line}"
        lines.append(line)
    return "\n".join(lines)<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalise inputs to sets for easier set operations
    if not isinstance(manifest_files, set):
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise TypeError("manifest_files must be an iterable of digests")
    else:
        manifest_set = manifest_files

    if not isinstance(digests_used, set):
        try:
            used_set = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digests")
    else:
        used_set = digests_used

    # Find any manifest digest that was never used
    missing = manifest_set - used_set
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"Missing digests from manifest that are not used: {missing_str}")

    # Verify that every used digest actually exists in our storage
    if hasattr(self, "analyzed_apk"):
        stored_digests = set(self.analyzed_apk.keys())
        unused = used_set - stored_digests
        if unused:
            unused_str = ", ".join(sorted(unused))
            raise ValueError(f"Digests used but not present in storage: {unused_str}")
    elif hasattr(self, "analyzed_files"):
        # If analyzed_files holds mapping from filename to list of digests
        stored_digests = set()
        for digests in self.analyzed_files.values():
            stored_digests.update(digests)
        unused = used_set - stored_digests
        if unused:
            unused_str = ", ".join(sorted(unused))
            raise ValueError(f"Digests used but not present in storage: {unused_str}")

    return True
<|return|>

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.
        """
        # basic type check
        try:
            from typing import Any
            # Delayed import to avoid circular imports
            InventoryValidator = Any
        except Exception:
            InventoryValidator = type(self)

        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # helper to safely get attribute or raise informative error
        def _get_attr(obj, name, required=True):
            if hasattr(obj, name):
                return getattr(obj, name)
            if required:
                raise AttributeError(f"Object {obj!r} is missing required attribute '{name}'")
            return None

        # version comparison
        self_version = _get_attr(self, "inventory_version", required=True)
        prior_version = _get_attr(prior, "inventory_version", required=True)
        if not isinstance(self_version, (int, float)) or not isinstance(prior_version, (int, float)):
            raise TypeError("inventory_version attributes must be numeric")
        if prior_version >= self_version:
            raise ValueError(f"Prior inventory version ({prior_version}) must be older than current ({self_version})")

        # species and parameters must match
        self_species = _get_attr(self, "species", required=True)
        prior_species = _get_attr(prior, "species", required=True)
        if set(self_species) != set(prior_species):
            raise ValueError("Species sets differ between current and prior inventories")

        self_params = _get_attr(self, "parameters", required=True)
        prior_params = _get_attr(prior, "parameters", required=True)
        if set(self_params) != set(prior_params):
            raise ValueError("Parameter sets differ between current and prior inventories")

        # optional matrix shape checks
        def _matrix_shape(mat):
            if mat is None:
                return (None, None)
            if hasattr(mat, "shape"):
                return mat.shape
            # attempt generic length based
            try:
                rows = len(mat)
                cols = len(mat[0]) if rows else 0
                return (rows, cols)
            except Exception:
                return (None, None)

        self_prop = _get_attr(self, "propensities", required=True)
        prior_prop = _get_attr(prior, "propensities", required=True)
        if _matrix_shape(self_prop) != _matrix_shape(prior_prop):
            raise ValueError("Propensities matrix shape differs between current and prior inventories")

        self_stoich = _get_attr(self, "stoichiometry_matrix", required=True)
        prior_stoich = _get_attr(prior, "stoichiometry_matrix", required=True)
        if _matrix_shape(self_stoich) != _matrix_shape(prior_stoich):
            raise ValueError("Stoichiometry matrix shape differs between current and prior inventories")

        return True
<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")

    # Attempt to retrieve the data for the requested version
    try:
        version_data = inventory[version]
    except Exception as exc:
        raise KeyError(f"Version '{version}' not found in inventory") from exc

    # Determine the source structure that holds logical path mappings
    source = None

    # Common patterns: dict of logical_path -> list/tuple of files
    if isinstance(version_data, dict):
        # If a `files` key exists, use its value; otherwise, use the dict itself
        if 'files' in version_data and isinstance(version_data['files'], (dict, list)):
            source = version_data['files']
        else:
            source = version_data
    # Or a list of (logical_path, files) tuples
    elif isinstance(version_data, list):
        source = version_data

    if source is None:
        raise TypeError(
            f"Unsupported inventory structure for version '{version}'. "
            f"Expected dict or list with mapping data, got {type(version_data)}."
        )

    result = {}
    if isinstance(source, dict):
        for logical_path, files in source.items():
            if isinstance(files, (list, tuple, set)):
                result[logical_path] = set(files)
            else:
                # If not iterable, put the single file into a set
                result[logical_path] = {files}
    elif isinstance(source, list):
        for entry in source:
            if not isinstance(entry, (list, tuple)) or len(entry) != 2:
                continue  # skip malformed entries
            logical_path, files = entry
            if isinstance(files, (list, tuple, set)):
                result[logical_path] = set(files)
            else:
                result[logical_path] = {files}
    else:
        # If source type is unexpected but iterable, try to iterate
        for item in source:
            try:
                logical_path, files = item
                if isinstance(files, (list, tuple, set)):
                    result[logical_path] = set(files)
                else:
                    result[logical_path] = {files}
            except Exception:
                continue

    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dict
    if not isinstance(fixity, dict):
        raise ValueError(
            f"Fixity block must be a dict, got {type(fixity).__name__}"
        )

    # Basic required keys
    required = {"file", "algorithm", "hash"}
    missing = required - fixity.keys()
    if missing:
        raise ValueError(f"Fixity block missing required keys: {sorted(missing)}")

    # Validate top‑level 'file' entry
    if not isinstance(fixity["file"], str):
        raise ValueError(
            f"Fixity 'file' must be a string, got {type(fixity['file']).__name__}"
        )

    # Convert manifest to set for fast lookup
    manifest_set = set(manifest_files)

    # Collect referenced filenames
    referenced = {fixity["file"]}

    # Handle potential nested file listings (e.g., in 'files' list)
    if "files" in fixity:
        files_block = fixity["files"]
        if not isinstance(files_block, list):
            raise ValueError("The 'files' key must contain a list")
        for idx, entry in enumerate(files_block):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry {idx} in 'files' must be a dict")
            if "file" not in entry:
                raise ValueError(f"Entry {idx} in 'files' missing 'file' key")
            fname = entry["file"]
            if not isinstance(fname, str):
                raise ValueError(
                    f"Entry {idx} 'file' must be a string, got {type(fname).__name__}"
                )
            referenced.add(fname)

    # Ensure all referenced files exist in the manifest
    unknown = referenced - manifest_set
    if unknown:
        raise ValueError(
            f"Fixity references unknown files: {sorted(unknown)}"
        )

    # All checks passed
    return True<|return|>

def files_list(path):
    """Return the files in `path`."""
    import os
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        try:
            files = []
            for entry in os.listdir(path):
                full_path = os.path.join(path, entry)
                if os.path.isfile(full_path):
                    files.append(os.path.abspath(full_path))
            return files
        except OSError as exc:
            raise RuntimeError(f"Error accessing contents of {path}") from exc
    raise ValueError(f"Unsupported path type: {path}")<|return|>

