def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not zip_path or not isinstance(zip_path, str):
        return {}

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                # Base name without extension
                basename = os.path.splitext(os.path.basename(info.filename))[0]
                if basename not in result:
                    result[basename] = {}
                # Read file contents
                try:
                    content = zf.read(info.filename)
                except Exception:
                    # If reading fails, skip this entry
                    continue
                result[basename][info.filename] = content
    except Exception:
        # If the zip file cannot be opened or read, return empty dict
        return {}
    return result<|return|>

