def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise ValueError('tzname_in_python2 expects a callable, got %r' % namefunc)
    import sys
    def inner(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] == 2 and isinstance(result, unicode):
            return result.encode()
        return result
    return inner<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    versions = {}
    # Try modern importlib.metadata first
    try:
        from importlib.metadata import distributions
        for dist in distributions():
            if dist.metadata is None:
                continue
            name = dist.metadata.get('Name')
            if name:
                versions[name] = dist.version
    except Exception:
        # Fallback to pkg_resources if available
        try:
            import pkg_resources
            for dist in pkg_resources.working_set:
                if dist.project_name:
                    versions[dist.project_name] = dist.version
        except Exception:
            # If anything goes wrong, we fall through to default
            pass

    # If we couldn't gather any versions, return a default entry
    if not versions:
        versions['default'] = 'unknown'
    return versions<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces
        A sequence of numeric pieces (int, str), a mapping with keys
        'major', 'minor', 'patch', or a dot‑separated string such as
        ``'1.2.3'``.  The function accepts any of these forms and
        normalises them into a list of integers.
    style : str
        One of ``'full'`` (major.minor.patch), ``'short'`` (major.minor),
        ``'compact'`` (numeric integer), ``'numeric'`` (same as compact)
        or ``'reversed'`` (patch.minor.major).  The comparison is
        case‑insensitive.

    Returns
    -------
    str
        The rendered version string.

    Raises
    ------
    ValueError
        If ``pieces`` cannot be interpreted or ``style`` is unknown.
    """
    # Normalise pieces into a list of integers
    if pieces is None:
        numeric_parts = []
    elif isinstance(pieces, str):
        # Split on dots
        try:
            parts = pieces.strip().split('.')
            numeric_parts = [int(p) for p in parts if p]
        except Exception as exc:
            raise ValueError("Cannot parse string pieces") from exc
    elif isinstance(pieces, Mapping):
        # Accept mapping with major/minor/patch keys
        try:
            numeric_parts = []
            for key in ('major', 'minor', 'patch'):
                val = pieces.get(key, 0)
                numeric_parts.append(int(val))
        except Exception as exc:
            raise ValueError("Mapping pieces contain non‑numeric values") from exc
    elif isinstance(pieces, Iterable) and not isinstance(pieces, (bytes, bytearray)):
        try:
            numeric_parts = [int(p) for p in pieces]
        except Exception as exc:
            raise ValueError("Iterable pieces contain non‑numeric values") from exc
    else:
        raise ValueError(f"Unsupported type for pieces: {type(pieces)}")

    # Handle empty pieces
    if not numeric_parts:
        return ''

    style = style.lower() if style else 'full'
    if style not in ('full', 'short', 'compact', 'numeric', 'reversed'):
        raise ValueError(f"Unknown style '{style}'. Supported styles "
                         "are: full, short, compact, numeric, reversed.")

    if style == 'full':
        return '.'.join(str(part) for part in numeric_parts)
    if style == 'short':
        # Use first two parts if available
        return '.'.join(str(part) for part in numeric_parts[:2])
    if style in ('compact', 'numeric'):
        # Combine major.minor.patch into a single integer:
        # major * 10000 + minor * 100 + patch (assumes 3 parts)
        # If less parts, pad with zeros
        major = numeric_parts[0]
        minor = numeric_parts[1] if len(numeric_parts) > 1 else 0
        patch = numeric_parts[2] if len(numeric_parts) > 2 else 0
        number = major * 10000 + minor * 100 + patch
        return str(number)
    if style == 'reversed':
        return '.'.join(str(part) for part in reversed(numeric_parts))<|return|>

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate that pieces is an iterable but not a string/bytes object
    if not hasattr(pieces, '__iter__') or isinstance(pieces, (str, bytes)):
        raise TypeError("pieces must be an iterable of strings or string-like objects")
    # Iterate over each element; treat as string for searching
    for elem in pieces:
        try:
            s = str(elem)
        except Exception:
            # Skip elements that cannot be converted to string
            continue
        if '+' in s:
            return '.'
    # If no '+' found, return '+'
    return '+'<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        if isinstance(commands, str):
            commands = [commands]
        else:
            raise TypeError("commands must be a string or an iterable of strings")
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be an iterable of strings")
    try:
        full_cmd = list(commands) + list(args)
    except Exception as e:
        raise ValueError("commands and args must be sequences of strings") from e
    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")
        if cwd:
            print(f"  cwd: {cwd}")
        if env:
            print(f"  env: {env}")
    try:
        import subprocess
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else None,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
        raise RuntimeError(msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(str(e)) from e
    return result.stdout<|return|>

