def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    for name, value in (('validate_objects', validate_objects),
                       ('check_digests', check_digests),
                       ('show_warnings', show_warnings)):
        if not isinstance(value, bool):
            raise TypeError(f'{name} must be a bool, got {type(value).__name__}')

    # Locate the hierarchy root – allow for different attribute names
    root = getattr(self, '_hierarchy', None)
    if root is None:
        root = getattr(self, 'hierarchy', None)
    if root is None:
        raise RuntimeError('Hierarchy root not found on object (no _hierarchy or hierarchy attribute).')

    num_objects = 0
    good_objects = 0

    def walk(node):
        nonlocal num_objects, good_objects
        # Handle container types
        if isinstance(node, dict):
            for child in node.values():
                walk(child)
        elif isinstance(node, list):
            for child in node:
                walk(child)
        else:
            # Treat any non-iterable as an object
            num_objects += 1
            ok = True

            # Optional object-specific validation
            if validate_objects:
                validator = getattr(node, 'validate', None)
                if callable(validator):
                    try:
                        ok = bool(validator())
                    except Exception as exc:  # pylint: disable=broad-except
                        ok = False
                        if show_warnings:
                            print(f'Warning: validation error in object {node!r}: {exc}')
                # If no validate method, assume pass

            # Optional digest check
            if check_digests:
                digest = getattr(node, 'digest', None)
                content = getattr(node, 'content', None)
                if digest is not None and content is not None:
                    try:
                        import hashlib
                        actual = hashlib.sha256(content.encode('utf-8')).hexdigest()
                        if actual != digest:
                            ok = False
                            if show_warnings:
                                print(f'Warning: digest mismatch in object {node!r}')
                    except (AttributeError, UnicodeEncodeError) as exc:  # pylint: disable=broad-except
                        ok = False
                        if show_warnings:
                            print(f'Warning: digest check failed for object {node!r}: {exc}')

            if ok:
                good_objects += 1

    walk(root)
    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os

    # Ensure the instance knows where the root should be
    if not hasattr(self, "root_path"):
        raise AttributeError("The instance must have a 'root_path' attribute.")

    root = os.path.abspath(str(self.root_path))

    # If the path exists, verify it is a suitable empty directory
    if os.path.exists(root):
        if not os.path.isdir(root):
            raise NotADirectoryError(f"Root path {root} exists and is not a directory.")
        if os.listdir(root):
            raise FileExistsError(
                f"Root directory {root} already contains files; cannot initialize."
            )
    else:
        os.makedirs(root, exist_ok=True)

    # Create standard OCFL subdirectories
    objects_dir = os.path.join(root, "objects")
    checkout_dir = os.path.join(root, "checkout")
    os.makedirs(objects_dir, exist_ok=True)
    os.makedirs(checkout_dir, exist_ok=True)

    # Create the OCFL root descriptor file if absent, or validate it
    ocfl_root_file = os.path.join(root, ".ocflroot")
    if not os.path.exists(ocfl_root_file):
        with open(ocfl_root_file, "w", encoding="utf-8") as f:
            f.write("1.0\n")
    else:
        with open(ocfl_root_file, "r", encoding="utf-8") as f:
            version = f.read().strip()
        if version != "1.0":
            raise ValueError(
                f"Unsupported OCFL version '{version}' in root {root}"
            )<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        return ""
    try:
        num = int(version)
        incremented = num + 1
        if version[0] == '0':
            width = len(version)
            return str(incremented).zfill(width)
        return str(incremented)
    except Exception:
        return ""<|return|>

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Verify that the provided path exists.
    if not os.path.exists(path):
        return "path does not exist"

    # Return immediately if the path is a file.
    if os.path.isfile(path):
        return "file"

    # The path is a directory.  Ensure it contains items.
    try:
        entries = os.listdir(path)
    except OSError as exc:
        return f"cannot read directory: {exc}"

    # Helper to detect directories beginning with '0='.
    def has_namaste_dir(entries_list):
        for name in entries_list:
            if os.path.isdir(os.path.join(path, name)) and name.startswith("0="):
                return True
        return False

    # Check for a storage root: it must contain an 'objects' subdir
    # that itself contains at least one namespaced directory '0=*'.
    if "objects" in entries:
        objects_path = os.path.join(path, "objects")
        if os.path.isdir(objects_path):
            try:
                obj_entries = os.listdir(objects_path)
            except OSError as exc:
                return f"cannot read objects directory: {exc}"
            for obj in obj_entries:
                if obj.startswith("0="):
                    return "root"

    # Check if the current directory itself contains a Namaste folder -> object
    full_entries = [os.path.join(path, e) for e in entries]
    for dirname in full_entries:
        if os.path.isdir(dirname) and os.path.basename(dirname).startswith("0="):
            return "object"

    # If we reach here, the directory does not match the expected OCFL patterns.
    return "not an OCFL directory"
<|return|>

