def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("response must not be None")
    if not hasattr(response, "__iter__") or isinstance(response, (str, bytes)):
        raise TypeError("response must be an iterable (e.g., list)")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator logic
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        raise RuntimeError("Error while paging the response") from exc<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise ValueError("Input iterable 'dicts' cannot be None.")
    result = {}
    for item in dicts:
        if not isinstance(item, dict):
            raise TypeError(f"Expected dict, got {type(item).__name__}.")
        for key, value in item.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Cannot add value for key '{key}': {exc}") from exc
            else:
                result[key] = value
    return result
<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None
    if val is None:
        return True
    # Handle string inputs
    if isinstance(val, str):
        stripped = val.strip()
        # Empty or whitespace only
        if not stripped:
