    # Guard against non-ArgumentParser objects
    if not hasattr(parser, '_actions'):
        return ''
    try:
        flags = []
        seen = set()
        for action in parser._actions:
            # Each action may have multiple option strings (e.g., ['-h', '--help'])
            for opt in getattr(action, 'option_strings', []):
                if opt not in seen:
                    seen.add(opt)
                    flags.append(opt)
        return ' '.join(flags)
