        return ''<|return|>

def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        return _vertex3tuple_cache
    except NameError:
        pass
    # Validate input
    if vertices is None:
        raise ValueError("vertices cannot be None")
    try:
        n = len(vertices)
    except Exception as e:
        raise TypeError("vertices must be a sequence with a defined length") from e
    if n < 3:
        raise ValueError("vertices must contain at least 3 elements to form a polygon")
    result = []
    for i in range(n):
        prev = vertices[(i - 1) % n]
        curr = vertices[i]
        nxt = vertices[(i + 1) % n]
        result.append((prev, curr, nxt))
    _vertex3tuple_cache = result
    return result<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple of single-character strings, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")
    for i, char in enumerate(alphabet):
        if not isinstance(char, str) or len(char) != 1:
            raise ValueError(f"alphabet element {i} is not a single-character string: {repr(char)}")

    base = len(alphabet)
    if base < 2 and number != 0:
        raise ValueError(f"alphabet must contain at least two distinct characters for non‑zero numbers, got base={base}")

    if number < 0:
        raise ValueError("number must be non‑negative")

    # Handle zero explicitly
    if number == 0:
        digits = [0]
    else:
        digits = []
        n = number
        while n:
            digits.append(n % base)
            n //= base

    # Convert digits to string (most significant first)
    chars = [alphabet[d] for d in reversed(digits)]
    result = ''.join(chars)

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")
        if len(result) < padding:
            pad_char = alphabet[0]
            result = pad_char * (padding - len(result)) + result

    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    :return: The updated flow_params dictionary
    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    for flow_key, flow_obj in flow_params.items():
        # Handle nested dictionaries directly under flow_params
        if isinstance(flow_obj, dict):
            if register_value in flow_obj:
                # If a register_number key already exists we preserve the
                # original value unless it is identical; in that case we skip.
                if register_number not in flow_obj or flow_obj[register_number] != flow_obj[register_value]:
                    flow_obj[register_number] = flow_obj.pop(register_value)
        # Handle lists of dictionaries (common for multiple flow steps)
        elif isinstance(flow_obj, list):
            for item in flow_obj:
                if isinstance(item, dict) and register_value in item:
                    if register_number not in item or item[register_number] != item[register_value]:
                        item[register_number] = item.pop(register_value)

    return flow_params<|return|>

