def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class as argument")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        if current not in seen:
            seen.add(current)
            queue.extend(current.__subclasses__())
    seen.discard(cls)
    return seen<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet elements must be unique")
    mapping = {ch: i for i, ch in enumerate(alphabet)}
    if string == "":
        return 0
    try:
        result = 0
        for ch in string:
            result = result * base + mapping[ch]
    except KeyError as e:
        raise ValueError(f"String contains character not in alphabet: {e.args[0]}") from None
    return result<|return|>

