def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex
    if platform == 'this':
        posix = not sys.platform.startswith('win')
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError(f"Unsupported platform value: {platform!r}")
    try:
        return shlex.split(s, posix=posix)
    except ValueError as err:
        # re-raise with additional context
        raise ValueError(f"shlex.split failed on input {s!r} with posix={posix}") from err<|return|>

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path

    src = Path(archive_path)
    if not src.is_file():
        raise FileNotFoundError(f"Archive {archive_path!s} does not exist or is not a file")

    tmp_root = Path(tmp_path).expanduser()
    tmp_root.mkdir(parents=True, exist_ok=True)

    # Determine destination directory
    if filename:
        dest_dir = tmp_root / filename
    else:
        # Use the base name of the archive without extensions
        base = src.stem
        # Handle double extensions like .tar.gz
        if src.name.endswith('.tar.gz') or src.name.endswith('.tar.bz2'):
            base = base.rsplit('.', 1)[0]
        dest_dir = tmp_root / base
    dest_dir.mkdir(parents=True, exist_ok=True)

    # Choose extraction command based on archive type
    name_lower = src.name.lower()
    try:
        if name_lower.endswith('.zip'):
            cmd = ['unzip', '-o', str(src), '-d', str(dest_dir)]
        elif name_lower.endswith('.tar.gz'):
            cmd = ['tar', '-xzf', str(src), '-C', str(dest_dir)]
        elif name_lower.endswith('.tar.bz2'):
            cmd = ['tar', '-xjf', str(src), '-C', str(dest_dir)]
        elif name_lower.endswith('.tar'):
            cmd = ['tar', '-xf', str(src), '-C', str(dest_dir)]
        elif name_lower.endswith('.tgz'):
            cmd = ['tar', '-xzf', str(src), '-C', str(dest_dir)]
        elif name_lower.endswith('.tbz2') or name_lower.endswith('.tbz'):
            cmd = ['tar', '-xjf', str(src), '-C', str(dest_dir)]
        else:
            raise ValueError(f"Unsupported archive format for {archive_path!s}")
        subprocess.check_call(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Extraction failed for {archive_path!s} to {dest_dir!s}"
        ) from exc
    except FileNotFoundError as exc:
        # Likely missing required utility (tar, unzip)
        raise RuntimeError(
            f"Required extraction utility not found for {archive_path!s}"
        ) from exc

    return f"file://{dest_dir.resolve()}"<|return|>

def addignored(ignored):
    """
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files,
    and return those files as a single string with each filename separated by a comma.
    """
    # Ensure `ignored` is an iterable of patterns
    try:
        patterns = list(ignored)
    except TypeError:
        # If not iterable (e.g., a single string), treat as one pattern
        patterns = [ignored]

    try:
        # Get ignored files (untracked files that match .gitignore or exclude standards)
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError:
        # If git command fails, return an empty string
        return ''

    # Parse the output into a list of filenames
    files = [line.strip() for line in output.splitlines() if line.strip()]

    # If patterns are provided, filter the list
    if patterns:
        try:
            import fnmatch
        except ImportError:
            # If fnmatch is unavailable, skip filtering
            pass
        else:
            filtered = []
            for f in files:
                for pat in patterns:
                    if fnmatch.fnmatch(f, pat):
                        filtered.append(f)
                        break
            files = filtered

    # Sort the list and join with commas
    files.sort()
    return ','.join(files)<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        host_str = str(host)
    except Exception:
        return False

    lc = host_str.lower()
    # Quick direct checks
    if lc in ("localhost", "localhost.localdomain", "127.0.0.1", "0.0.0.0", "::1"):
        return True

    try:
        infos = socket.getaddrinfo(host_str, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in infos:
        if family not in (socket.AF_INET, socket.AF_INET6):
            continue
        addr = sockaddr[0]

        if family == socket.AF_INET:
            # Any 127.x.x.x is local
            try:
                first_octet = int(addr.split('.', 1)[0])
            except Exception:
                continue
            if first_octet == 127:
                return True

        if family == socket.AF_INET6:
            # IPv6 local ::1
            try:
                # Convert to binary form
                bin_addr = socket.inet_pton(socket.AF_INET6, addr)
                if bin_addr == b'\x00' * 15 + b'\x01':
                    return True
            except Exception:
                continue

    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows base environment
        if os.name != 'nt':
            return False

        # Git Bash sets the OSTYPE environment variable starting with 'msys'
        ostype = os.getenv('OSTYPE', '').lower()
        if ostype.startswith('msys'):
            return True

        # Some Git Bash installations also expose the MSYSTEM variable
        if os.getenv('MSYSTEM'):
            return True

        return False
    except Exception:
        # Any unexpected failure defaults to False for safety
        return False<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve full path relative to current working directory
    config_path = os.path.abspath(config_filename)

    # Abort if file exists and overwrite flag not set
    if os.path.isfile(config_path) and not overwrite:
        raise FileExistsError(f"File '{config_path}' already exists and overwrite is set to False")

    # Ensure directory exists
    config_dir = os.path.dirname(config_path)
    if config_dir:
        try:
            os.makedirs(config_dir, exist_ok=True)
        except OSError as e:
            raise OSError(f"Failed to create directories for '{config_dir}': {e}")

    # Write the file with specified mode and handle any I/O errors
    try:
        with open(config_path, 'w') as f:
            f.write(rendered_config)
        os.chmod(config_path, mode)
    except OSError as e:
