def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised."""
    # Extract the variable name and optional default from the matcher.
    # The matcher is expected to be a regex match object with group(1) = name and group(2) = default (if any).
    try:
        name = matcher.group(1)
    except AttributeError:
        raise TypeError("matcher must provide a 'group' method to retrieve the variable name")
    try:
        default = matcher.group(2)
    except IndexError:
        default = None

    # Attempt to read the environment variable.
    if name in os.environ:
        return os.environ[name]
    # If not found and a default was specified, return that.
    if default is not None:
        return default
    # No variable and no default: raise an informative error.
    raise KeyError(f"Environment variable '{name}' not set and no default provided")<|return|>

