def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mu = 0.2
    sigma = 0.1
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be a numeric type or array.") from e
    denom = sigma * np.sqrt(2 * np.pi)
    y = (1.0 / denom) * np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))
    if np.isscalar(x):
        return float(y)
    return y<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import logging
    # yaml and toml are assumed to be imported elsewhere
    config_map = {}
    error_records = []

    def _expand_env(value):
        """Recursively expand environment variables in strings within data structures."""
        if isinstance(value, dict):
            return {_expand_env(k): _expand_env(v) for k, v in value.items()}
        if isinstance(value, (list, tuple, set)):
            expanded = [_expand_env(v) for v in value]
            if isinstance(value, list):
                return expanded
            if isinstance(value, tuple):
                return tuple(expanded)
            return set(expanded)
        if isinstance(value, str):
            return os.path.expandvars(value)
        return value

    if not hasattr(config_filenames, "__iter__"):
        raise ValueError("config_filenames must be an iterable of file paths")

    for filename in config_filenames:
        parsed_config = None
        try:
            with open(filename, "r", encoding="utf-8") as fh:
                content = fh.read()
            lowername = filename.lower()
            if lowername.endswith((".yaml", ".yml")):
                parsed_config = yaml.safe_load(content)
            elif lowername.endswith(".toml"):
                parsed_config = toml.loads(content)
            elif lowername.endswith(".json"):
                parsed_config = json.loads(content)
            else:
                raise ValueError(f"Unsupported file extension for '{filename}'")

            if parsed_config is None:
                parsed_config = {}

            if not isinstance(parsed_config, dict):
                raise ValueError(f"Configuration in '{filename}' is not a dict")

            if overrides:
                # shallow merge: overrides override parsed_config entries
                parsed_config.update(overrides)

            if resolve_env:
                parsed_config = _expand_env(parsed_config)

        except Exception as exc:
            # Build a log record for the error
            message = f"Failed to parse configuration file '{filename}'. {exc}"
            record = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=message,
                args=(),
                exc_info=exc,
            )
            error_records.append(record)
        finally:
            config_map[filename] = parsed_config
    return config_map, error_records<|return|>

