        raise TypeError("values must be an iterable of strings") from exc

    parsed_bookmarks = []
    for raw_value in values:
        if not isinstance(raw_value, str):
            raise TypeError(
                f"Each bookmark must be a string; got {type(raw_value).__name__}"
            )
        raw_text = raw_value.strip()
        if not raw_text:
            continue  # skip empty entries
        # If the class defines a Bookmark inner class with a from_raw method, use it
        if getattr(cls, "Bookmark", None) and hasattr(cls.Bookmark, "from_raw"):
            try:
                bookmark = cls.Bookmark.from_raw(raw_text)
            except Exception as exc:
                raise ValueError(f"Failed to parse bookmark '{raw_text}': {exc}") from exc
        else:
            # Fallback: store raw string as bookmark representation
            bookmark = raw_text
        parsed_bookmarks.append(bookmark)

    return cls(parsed_bookmarks)<|return|>

