def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Determine whether the cache is empty by checking its truthiness or length
    if not self:
        raise KeyError('cache is empty')

    # The least recently used node is the first real node after the head sentinel
    try:
        node = self._head[2]
    except Exception:
        raise KeyError('cache is empty')

    # If the head points directly to the tail sentinel, the cache is empty
    if not hasattr(self, "_tail") or node is self._tail:
        raise KeyError('cache is empty')

    key, value = node[0], node[1]

    # Remove the node from the internal linked list
    try:
        self._remove(node)
    except AttributeError:
        pass  # If the method is not present, we silently ignore

    # Remove the mapping entry if a dictionary attribute exists
    if hasattr(self, "_dict"):
        try:
            del self._dict[key]
        except KeyError:
            pass
    elif hasattr(self, "_cache"):
        try:
            del self._cache[key]
        except KeyError:
            pass

    return key, value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to use OrderedDict's popitem with last=True (most recently used)
        return super().popitem(last=True)
    except (AttributeError, TypeError):
        # Fallback to plain dict popitem (arbitrary but ensures removal)
        try:
            return dict.popitem(self)
        except KeyError as e:
            # Re‑raise with clearer message if dictionary is empty
            raise KeyError("popitem from empty dictionary") from e<|return|>

