def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if not request or not hasattr(request, "body"):
        return False

    body = request.body
    # handle body that might be bytes, bytearray or str
    try:
        if isinstance(body, (bytes, bytearray)):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = body
    except Exception:
        return False

    # 1. Attempt to parse JSON (public) payload
    try:
        data = json.loads(body_str)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # 2. Attempt to parse XML (private) payload
    try:
        xml_root = etree.fromstring(body if isinstance(body, (bytes, bytearray)) else body_str.encode("utf-8"))
        # Diaspora envelopes usually use the tag <magicEnvelope>
        if xml_root.tag == "magicEnvelope":
            return True
    except Exception:
        pass

    # 3. Legacy payload: older messages sometimes just start with a magic header
    #    Check for a common legacy pattern value (example: "Diaspora")
    if body_str.lstrip().lower().startswith("diaspora"):
        return True

    return False<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib
    except Exception:
        return None

    if not isinstance(url, str) or not url:
        return None

    try:
        scheme = urllib.parse.urlparse(url).scheme
    except Exception:
        return None
    if scheme not in ("http", "https", "ftp", "ftps"):
        return None

    # Build a HEAD request
    try:
        req = urllib.request.Request(url, method="HEAD")
    except TypeError:  # pragma: no cover
        # older Python versions: fall back to GET and ignore body
        req = urllib.request.Request(url)

    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get("Content-Type")
    except urllib.error.HTTPError:
        # HEAD may be disallowed; try a GET request as fallback
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                return resp.headers.get("Content-Type")
        except Exception:
            return None
    except Exception:
        return None<|return|>

