def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid url: must be a non-empty string")
    # Ensure url starts with http:// or https://
    if not url.lower().startswith(("http://", "https://")):
        raise ValueError("URL must begin with http:// or https://")
    # Default well‑known path if none supplied
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    elif not isinstance(document_path, str):
        raise ValueError("document_path must be a string if provided")
    # Normalise the path: it should start with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    # Build the full href, avoiding duplicate slashes
    href = f"{url.rstrip('/')}{document_path}"
    # NodeInfo supports schema 1.0 and 2.0; return both
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href,
            },
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href,
            },
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        logger.warning("parse_diaspora_webfinger: document is not a string")
        return None
    result = {}
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            links = data.get("links", [])
            for link in links:
                if not isinstance(link, dict):
                    continue
                rel = link.get("rel", "")
                href = link.get("href", "")
                if not href:
                    continue
                # Normalize rel strings
                rel_vals = [r.lower() for r in rel.split()] if isinstance(rel, str) else []
                if "hcard" in rel_vals or "http://www.w3.org/ns/activitystreams#hcard" in rel_vals:
                    result["hcard_url"] = href
                if "inbox" in rel_vals or "http://activitypub.org/ns/#inbox" in rel_vals:
                    result["inbox_url"] = href
            if result:
                return result
    except Exception as e:
        # Not a JSON webfinger; fall back to XRD parsing
        pass

    # Attempt to parse as XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        # XRD typically resides in the namespace xrd: http://docs.oasis-open.org/ns/xri/xrd-1.0
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        for link in root.findall(".//xrd:Link", ns):
            try:
                rel = link.attrib.get("rel", "")
                href = link.attrib.get("href", "")
                if not href:
                    continue
                rel_vals = [r.lower() for r in rel.split()] if isinstance(rel, str) else []
                # Simple matching: check for substring 'hcard' or 'inbox'
                if "hcard" in rel_vals or "hcard" in rel or "http://www.w3.org/ns/activitystreams#hcard" in rel:
                    result["hcard_url"] = href
                if "inbox" in rel_vals or "inbox" in rel or "http://activitypub.org/ns/#inbox" in rel:
                    result["inbox_url"] = href
            except Exception:
                continue
        if result:
            return result
    except Exception as exc:
        logger.warning("parse_diaspora_webfinger: failed to parse XRD: %s", exc)
        return None

    # If we reach here, parsing failed
    logger.warning("parse_diaspora_webfinger: unable to parse document")
    return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle:
            return None
        # Ensure we have a host part; default to handle if no '@'
        host = handle.split("@")[-1]
        # Build the webfinger request URL
        import urllib.request, urllib.parse, urllib.error
        url = f"https://{host}/.well-known/webfinger?resource=acct:{urllib.parse.quote(handle)}"
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return None
            data = response.read()
            # Return str, decoding bytes if necessary
            if isinstance(data, bytes):
                return data.decode("utf-8", errors="replace")
            return data
    except (urllib.error.HTTPError, urllib.error.URLError, OSError, ValueError):
        # Any network/IO/error is swallowed; return None
        return None<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of fully-qualified file paths found
       in the given directories.  ``settings_dirs`` can be a
       string or an iterable of strings.  ``spec_option`` can be:

       * ``None`` – return all files,
       * a string – interpreted as a file extension (e.g.
         ``'.ini'``, ``'.cfg'``) or a glob pattern;
       * a callable – used as a filter for file names.

       Directories that cannot be read are silently skipped.
    """
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    if not hasattr(settings_dirs, "__iter__"):
        raise TypeError("settings_dirs must be a string or an iterable of strings")

    results = []
    for directory in settings_dirs:
        try:
            if not os.path.isdir(directory):
                # Skip non-directories
                continue
            # Determine files to consider
            files = os.listdir(directory)
            # Apply spec_option
            if spec_option is None:
                matched = files
            elif callable(spec_option):
                matched = [f for f in files if spec_option(f)]
            elif isinstance(spec_option, str):
                if "*" in spec_option or "?" in spec_option or "[" in spec_option:
                    # Treat as a glob pattern relative to the directory
                    pattern = os.path.join(directory, spec_option)
                    matched = [os.path.basename(p) for p in glob.glob(pattern)]
                else:
                    # Treat as a file extension filter
                    matched = [f for f in files if f.endswith(spec_option)]
            else:
                # Unsupported spec_option type – raise an error
                raise TypeError("spec_option must be None, a callable, or a string")
            for f in matched:
                full_path = os.path.join(directory, f)
                if os.path.isfile(full_path):
                    results.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(results)<|return|>

