    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as exc:
        raise IRValidatorException(f"YAML parsing error: {exc}") from exc
    if data is None:
        raise IRValidatorException("Spec content is empty or invalid")
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        # Resolve file path and ensure it exists
        try:
            path = str(yaml_file)
            with open(path, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except (yaml.YAMLError, Exception) as exc:
            # Catch generic exceptions that may occur during YAML parsing
            raise IRValidatorException(f"Error parsing YAML file '{yaml_file}': {exc}")

        if not isinstance(data, dict):
            raise IRValidatorException(f"The YAML file '{yaml_file}' does not contain a top‑level mapping")

        # Determine required fields (class attribute or default to empty list)
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            raise IRValidatorException(
                f"Missing mandatory field(s) in '{yaml_file}': {', '.join(missing_fields)}"
            )

        return data<|return|>

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        try:
            includes = parser_dict.get('include')
            # No include directive to process
            if not includes:
                return
            if not isinstance(includes, dict):
                raise ValueError("Parser 'include' directive must be a dict")

            for key, inc_val in includes.items():
                # If the key does not exist, simply add it
                if key not in parser_dict or parser_dict[key] is None:
                    parser_dict[key] = inc_val
                else:
                    # If both existing and included values are dicts, merge them
                    if isinstance(parser_dict[key], dict) and isinstance(inc_val, dict):
                        merged = {**parser_dict[key], **inc_val}
                        parser_dict[key] = merged
                    else:
                        # For non-dict values, the included value overrides the existing one
                        parser_dict[key] = inc_val

            # Remove the include key after processing to avoid duplication
            parser_dict.pop('include', None)
        except Exception as e:
            # Wrap any exception for easier debugging downstream
            raise RuntimeError(f"_include_groups failed: {e}") from e<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Attempt to obtain a mapping of defaults from the spec.
    spec_defaults = {}
    try:
        if hasattr(self, "spec"):
            # Prefer any explicit to_dict() method.
            if hasattr(self.spec, "to_dict") and callable(self.spec.to_dict):
                spec_defaults = self.spec.to_dict()
            else:
                # Fall back to the spec's __dict__.
                spec_defaults = dict(vars(self.spec))
    except Exception:
        # If spec doesn't expose a dictionary, leave defaults empty.
        spec_defaults = {}

    # Prepare the result dictionary.
    defaults = dict(spec_defaults)

    # Ensure defaults are populated from the defined arguments.
    for arg in getattr(self, "args", []):
        # Skip any non-option objects.
        if not hasattr(arg, "name"):
            continue
        name = arg.name

        # If the name is already in defaults from the spec, skip.
        if name in defaults:
            continue

        # Add the default from the argument if it exists.
        if hasattr(arg, "default"):
            val = getattr(arg, "default")
            # Reject `NoDefault` sentinel if present.  If `NoDefault` is not defined,
            # the check will simply skip the comparison and use the value.
            try:
                from .errors import NoDefault  # pragma: no cover
                if isinstance(val, NoDefault):
                    continue
            except Exception:
                # Fallback: treat `None` as an explicit default until overridden.
                pass
            defaults[name] = val

        # Handle nested dictionary option schemes recursively.
        if hasattr(arg, "scheme") and hasattr(arg, "default") and isinstance(arg, DictOption):
            # `build_defaults` returns the dictionary of defaults for the nested scheme.
            try:
                nested_defaults = arg.scheme.build_defaults()
            except Exception:
                nested_defaults = {}
            if nested_defaults:
                defaults[name] = nested_defaults

    return defaults<|return|>

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {
        # Deprecated argument name : current argument name
        'old_input': 'new_input',
        'legacy_flag': 'modern_flag',
        'use_color': 'color_output',
    }<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Retrieve mapping of deprecated to current names; default to empty dict
        deprecated_map = getattr(self, "deprecated_args", {})

        # Check CLI arguments for deprecation
        for arg, value in cli_args.items():
            if arg in deprecated_map:
                warnings.warn(
                    f"Argument '{arg}' is deprecated; use '{deprecated_map[arg]}' instead. Argument from CLI.",
                    DeprecationWarning,
                )

        # Check answer file arguments for deprecation, ignoring ones overridden by CLI
        for arg, value in answer_file_args.items():
            if arg in deprecated_map and arg not in cli_args:
                warnings.warn(
                    f"Argument '{arg}' is deprecated; use '{deprecated_map[arg]}' instead. Argument from answer file.",
                    DeprecationWarning,
                )<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate arguments
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non‑empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non‑empty string")

    # Attempt to retrieve the command entry
    try:
        cmd_entry = self.commands[command_name]
    except Exception as exc:
        raise KeyError(f"Command '{command_name}' not found") from exc

    # The options/arguments can be located under several possible keys
    spec = None
    for key in ("options", "arguments"):
        if isinstance(cmd_entry, dict) and key in cmd_entry:
            spec = cmd_entry[key].get(argument_name)
            if spec is not None:
                return spec

    # If the command itself implements a lookup method
    if hasattr(cmd_entry, "get_option"):
        try:
            return getattr(cmd_entry, "get_option")(argument_name)
        except Exception:
            pass

    # Finally, if spec not found raise an informative error
    raise KeyError(
        f"Argument or option '{argument_name}' not found for command '{command_name}'"
    )<|return|>

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        # If no arguments provided, return empty list
        if not args:
            return []

        # Normalize to a list of strings
        if isinstance(args, str):
            try:
                # Very simple split; preserves quoted substrings with spaces
                import shlex
                arg_list = shlex.split(args)
            except Exception:
                arg_list = args.split()
        elif isinstance(args, (list, tuple)):
            arg_list = list(args)
        else:
            # Unsupported type; return empty list
            return []

        # Define known silent flags and the names we want to return
        silent_flags = {
            '--quiet': 'quiet',
            '-q': 'quiet',
            '--silent': 'silent',
            '-s': 'silent',
            '--no-output': 'no_output',
            '-n': 'no_output',
        }

        silent_names = []
        for arg in arg_list:
            # Consider only arguments that begin with a dash
            if not isinstance(arg, str):
                continue
            if not arg.startswith('-'):
                continue
            # Direct match
            if arg in silent_flags:
                silent_names.append(silent_flags[arg])
            else:
                # Strip leading dashes and check if the flag is in our set
                stripped = arg.lstrip('-')
                # Handle options with '=' e.g., --quiet=1
                if '=' in stripped:
                    base, _ = stripped.split('=', 1)
                else:
                    base = stripped
                # Check against known base names
                for flag, name in silent_flags.items():
                    flag_name = flag.lstrip('-')
                    if base == flag_name:
                        silent_names.append(name)
                        break

        return silent_names)<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Accept only a mapping of argument names to their values or
    # dictionaries containing ``value`` and an optional ``maxlen`` key.
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    for arg_name, arg_desc in args.items():
        # If the descriptor is a dict, pull out the value and the max length.
        if isinstance(arg_desc, dict):
            value = arg_desc.get("value")
            maxlen = arg_desc.get("maxlen")
        else:
            value = arg_desc
            maxlen = None

        # No length constraint specified – nothing to validate.
        if maxlen is None:
            continue

        # Ensure the max length is a non‑negative integer.
        if not isinstance(maxlen, int) or maxlen < 0:
            raise ValueError(
                f"maxlen for argument '{arg_name}' must be a non‑negative integer, got {maxlen!r}"
            )

        # Only check the length if the value supports ``__len__``.
        if not hasattr(value, "__len__"):
            continue

        if len(value) > maxlen:
            raise ValueError(
                f"argument '{arg_name}' length {len(value)} exceeds maximum allowed {maxlen}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")
    arg_defs = self.parsed_yaml.get('args', {})
    for name, value in args.items():
        definition = arg_defs.get(name)
        if not definition:
            continue
        choices = definition.get('choices')
        if choices is None:
            continue
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{name}'. Expected one of "
                f"{list(choices)!r}, got {value!r}"
            )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: Iterable of values to be validated. Expected numeric.
    :raises TypeError: If an argument is not a real number.
    :raises ValueError: If an argument is outside the defined bounds.
    :return: The original ``args`` if all values satisfy the bounds.
    """
    # Retrieve bounds from instance attributes; fall back to None if not defined
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    # If neither bound is defined, nothing to validate
    if min_val is None and max_val is None:
        return args

    # Ensure we can iterate over ``args`` safely
    if not isinstance(args, (list, tuple)):
        args = list(args)

    for index, value in enumerate(args):
        # Convert value to a float for numeric comparison
        try:
            num = float(value)
        except Exception as exc:
            raise TypeError(
                f"Argument at position {index} is not a numeric value: {value!r}"
            ) from exc

        if min_val is not None and num < min_val:
            raise ValueError(
                f"Argument {value!r} at position {index} below minimum {min_val}"
            )
        if max_val is not None and num > max_val:
            raise ValueError(
                f"Argument {value!r} at position {index} above maximum {max_val}"
            )

    return args<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate basic input types
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict with option specifications")

    # Merge special attributes into the spec dict
    attributes = spec_option.copy()
    attributes.setdefault("subcommand", subcommand)
    attributes.setdefault("option_name", option_name)

    # Prevent accidental override of built‑in object attributes
    reserved = {"__dict__", "__weakref__", "__module__", "__doc__", "__init__"}
    for key in reserved:
        if key in attributes:
            attributes.pop(key)

    try:
        # Dynamically create a simple class that holds the specs
        ComplexType = type(type_name, (object,), attributes)
    except Exception as exc:
        raise TypeError(f"Unable to create complex type '{type_name}': {exc}") from exc

    # Return an instance of the newly created class
    return ComplexType()
<|return|>

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Define a set of known control arguments.  These are optional
        # and may be extended by subclasses if required.
        control_keys = {
            'destroy', 'cleanup', 'debug', 'verbose', 'config', 'log-file'
        }

        if args is None:
            return {}, {}

        control_args = {}
        nested_args = {}

        # Helper to parse a single key/value pair
        def _add_kv(k, v, ctx):
            if k in control_keys:
                control_args[k] = v
            else:
                nested_args[k] = v

        try:
            if isinstance(args, dict):
                # Already a mapping, so simply iterate.
                for k, v in args.items():
                    _add_kv(k, v, args)
            elif isinstance(args, (list, tuple)):
                # Parse a list that may contain command-line style
                # elements such as '--key=value', '-k', 'value' pairs.
                it = iter(args)
                for token in it:
                    if token.startswith('--'):
                        # Long option
                        if '=' in token:
                            k, v = token[2:].split('=', 1)
                        else:
                            k = token[2:]
                            # Fetch the next value if available
                            try:
                                v = next(it)
                            except StopIteration:
                                v = None
                        _add_kv(k, v, args)
                    elif token.startswith('-') and len(token) > 1:
                        # Short option
                        k = token[1:]
                        try:
                            v = next(it)
                        except StopIteration:
                            v = None
                        _add_kv(k, v, args)
                    else:
                        # Positional or malformed token – ignore or log
                        continue
            else:
                # Unsupported type: raise an informative error
                raise TypeError(
                    f"Unsupported type for args: {type(args).__name__}. "
                    "Expected dict, list, or tuple."
                )
        except Exception as exc:
            # Log and re‑raise to surface hidden parsing bugs.
            LOG.error(
                "Error parsing arguments in get_nested_custom_and_control_args: %s",
                exc, exc_info=True
            )
            raise

        return control_args, nested_args<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List or dictionary of extra-vars
    :return: Updated dictionary
    """
    if vars_dict is None:
        return {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            else:
                raise ValueError("Each item in extra_vars list must be a dictionary")
    else:
        raise TypeError("extra_vars must be a dictionary or a list of dictionaries")
    return vars_dict
<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    # Helper to convert a single string value to a more appropriate type
    def _convert_value(val):
        if val is None:
            return val
        if not isinstance(val, str):
            return val
        lowered = val.lower()
        # Boolean values
        if lowered in ("true", "false"):
            return lowered == "true"
        if lowered in ("1", "0"):
            return bool(int(val))
        # Integer values
        if val.isdigit() or (val.startswith("-") and val[1:].isdigit()):
            try:
                return int(val)
            except ValueError:
                pass
        # Float values
        try:
            f = float(val)
            return f
        except ValueError:
            pass
        # List values separated by commas
        if "," in val:
            parts = [p.strip() for p in val.split(",")]
            new_parts = [_convert_value(p) for p in parts]
            return new_parts
        # Default to the original string
        return val

    # Iterate through the dictionary, converting each value in place
    for key, val in list(values_dict.items()):
        try:
            new_val = _convert_value(val)
            values_dict[key] = new_val
        except Exception:
            # Preserve the original value if conversion fails
            values_dict[key] = val
    # No explicit return value; the dictionary is mutated in place.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    try:
        # Helper to load YAML if available, otherwise JSON
        def _load_spec(path):
            try:
                import yaml
                with open(path, 'r', encoding='utf-8') as f:
                    return yaml.safe_load(f) or {}
            except ImportError:
                try:
                    import json
                    with open(path, 'r', encoding='utf-8') as f:
                        return json.load(f)
                except Exception:
                    return {}
            except Exception:
                return {}

        # Normalize plugin_dir
        if not isinstance(plugin_dir, str):
            return {}
        if not os.path.isdir(plugin_dir):
            return {}

        # Potential spec file names
        spec_filenames = ['plugin.yaml', 'plugin.yml', 'plugin.json']
        spec_path = None
        for filename in spec_filenames:
            candidate = os.path.join(plugin_dir, filename)
            if os.path.isfile(candidate):
                spec_path = candidate
                break

        if not spec_path:
            return {}

        spec_data = _load_spec(spec_path)
        if not isinstance(spec_data, dict):
            return {}

        flat_dict = {}

        def _flatten(d, parent_key=''):
            for k, v in d.items():
                new_key = f'{parent_key}.{k}' if parent_key else k
                if isinstance(v, dict):
                    _flatten(v, new_key)
                else:
                    flat_dict[new_key] = v

        _flatten(spec_data)
        return flat_dict

    except Exception:
        # In case of any unexpected error, return empty dict for safety
        return {}<|return|>
